import {form,area,text,select as sel} from '../ui.mjs';
import {qrSVG} from './qr-core.mjs';
import {vectorResult} from './vector.mjs';
export function setupQR(tool,mount,out){let disposed=false;form(mount,[area('text','Text or URL','https://nepocore.com'),sel('style','Code style',[['rounded','Soft rounded'],['square','Classic squares'],['dots','Playful dots']],'rounded'),sel('level','Error correction',[['M','Medium · 15%'],['Q','Quartile · 25%'],['H','High · 30%'],['L','Low · 7%']],'M'),text('ink','Code color','#183d36','color'),text('paper','Background color','#ffffff','color'),{...text('caption','Caption (optional)','Scan & explore','text',true),required:false}],async v=>{if(new TextEncoder().encode(v.text).length>2000)throw Error('Use up to 2,000 UTF-8 bytes. Short content makes a simpler, easier-to-scan code.');if(v.caption.length>50)throw Error('Keep the caption to 50 characters.');const {default:qrcode}=await import('../assets/vendor/qrcode.mjs');if(disposed)return;qrcode.stringToBytes=s=>Array.from(new TextEncoder().encode(s));const qr=qrcode(0,v.level);qr.addData(v.text,'Byte');try{qr.make();}catch{throw Error('This content is too long for the selected correction level. Shorten it or choose a lower correction level.');}const r=qrSVG(qr,v);vectorResult(out,r.svg,'nepocore-qr',{width:r.width,height:r.height,label:'Your custom QR',details:[['Code style',v.style],['Code grid',r.modules+' × '+r.modules],['Quiet zone','4 modules on every side'],['Color contrast',r.contrast.toFixed(1)+':1']],note:'Static code: no redirects, tracking service or expiry. Always test your exported code with a scanner before printing or sharing.'});},{label:'Create QR code',note:'Pick your style and colors. Dark modules, a light background and the built-in clear margin help scanners read your code.'});return()=>{disposed=true;};}
